	#region TEST List Process Child Windows	[DllImport("user32.dll", SetLastError = true, CharSet = CharSet.Unicode)]	public static extern bool EnumWindows(EnumWindowsProc enumProc, IntPtr lParam);	public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);	[DllImport("user32.dll", SetLastError = true, CharSet = CharSet.Unicode)]	public static extern int GetClassName(IntPtr hWnd, StringBuilder lpClassName, int nMaxCount);		[DllImport("user32.dll", SetLastError = true, CharSet = CharSet.Unicode)]		public static extern int GetWindowThreadProcessId(IntPtr hWnd, out int lpdwProcessId);	public List<IntPtr> GetChildHandles() {		if (!VsCodeIsRunning) return new List<IntPtr>();		var handleList = new List<IntPtr>();		var processes = process.GetChildProcesses();		Console.WriteLine("Children handles are:");		Process proc = null;		// Cycle through all top-level windows		EnumWindows(delegate (IntPtr hWnd, IntPtr lParam) {			// Get PID of current window			NativeMethods.GetWindowThreadProcessId(hWnd, out int processId);			// Get process matching PID			proc = processes.Where(p => p.Id == processId).FirstOrDefault();			if (proc != null) {				// Get class name of current window				StringBuilder classNameBuilder = new StringBuilder(256);				GetClassName(hWnd, classNameBuilder, 256);				Console.WriteLine($"ClassName:{classNameBuilder}");				// Check if class name matches what we're looking for				if (classNameBuilder.ToString() == "ball_02") {					Console.WriteLine($"{proc.ProcessName} process found with ID {proc.Id}, handle {hWnd.ToString("X")}");					handleList.Add(hWnd);				}			}			// return true so that we iterate through all windows			return true;		}, IntPtr.Zero);		return handleList;	}	#endregion// get all child windows	private List<IntPtr> GetAllChildrenWindowHandles(IntPtr hParent,  int maxCount) {		var result = new List<IntPtr>();		int ct = 0;		IntPtr prevChild = IntPtr.Zero;		IntPtr currChild = IntPtr.Zero;		while (true && ct < maxCount) {			currChild = NativeMethods.FindWindowEx(hParent, prevChild, null, null);			if (currChild == IntPtr.Zero) break;			result.Add(currChild);			prevChild = currChild;			++ct;		}		return result;	}